"O login da versão web ainda não foi configurado.":"El inicio de sesión de la versión web aún no está configurado.",
"Dica: para usar como app, toque em Compartilhar (□↑) e depois em \"Adicionar à Tela de Início\".":"Consejo: para usarla como app, toca Compartir (□↑) y luego \"Añadir a pantalla de inicio\".",
