"Para acompanhar o saldo dela.":"Para seguir su saldo.",
"Três passos para o app começar a mostrar o seu mês. Dá para pular e fazer depois.":"Tres pasos para que la app empiece a mostrar tu mes. Puedes saltarlos y hacerlo después.",
"Importe de uma planilha .xlsx, .ods ou .csv: o app entende o jeito dela e mostra tudo antes de importar.":"Importa desde una hoja de cálculo .xlsx, .ods o .csv: la app entiende su formato y muestra todo antes de importar.",
"Boas-vindas!":"¡Bienvenido!",
"O nome aparece no topo do Resumo e nas mensagens do app. Fica só neste app: numa conta compartilhada, cada pessoa vê o próprio nome no seu celular.":"El nombre aparece arriba en el Resumen y en los mensajes de la app. Se queda solo en esta app: en una cuenta compartida, cada persona ve su propio nombre en su celular.",
"Digite o seu nome (ou um apelido).":"Escribe tu nombre (o un apodo).",
"Este é o Cofrim: seus ganhos, gastos, contas e investimentos num lugar só, salvos na sua conta Google. Veja em um minuto como usar.":"Este es Cofrim: tus ingresos, gastos, cuentas e inversiones en un solo lugar, guardados en tu cuenta de Google. Mira en un minuto cómo usarlo.",
"Toque no + (ou nos atalhos do Resumo) e informe só o valor e a categoria; o resto fica em \"Mais opções\". Os gastos que você mais repete viram botões.":"Toca el + (o los accesos del Resumen) e indica solo el valor y la categoría; el resto está en \"Más opciones\". Los gastos que más repites se vuelven botones.",
"Num salário, escolha em Mais opções o dia em que cai, como o 5º dia útil.":"En un salario, elige en Más opciones el día en que cae, como el 5.º día hábil.",
"Gastos do mês e do ano, contas a vencer, gastos por categoria e contas bancárias. Há muito mais (previsão, gráficos, metas, investimentos): toque em \"Ver mais informações no resumo\", no fim da tela, ou no menu (três barras), no topo › Reorganizar esta tela.":"Gastos del mes y del año, cuentas por vencer, gastos por categoría y cuentas bancarias. Hay mucho más (previsión, gráficos, metas, inversiones): toca \"Ver más información en el resumen\", al final de la pantalla, o el menú (tres barras), arriba › Reorganizar esta pantalla.",
"Separados em Assinaturas, Fixos e anuais, Parceladas e Ocasionais, com busca e filtros. Deslize um lançamento para a esquerda para excluir; numa conta com vencimento, para a direita marca como paga. Na mesma aba ficam o orçamento, as previsões de gastos e a saúde financeira do mês.":"Separados en Suscripciones, Fijos y anuales, A cuotas y Ocasionales, con búsqueda y filtros. Desliza un movimiento a la izquierda para eliminarlo; en una cuenta con vencimiento, a la derecha la marca como pagada. En la misma pestaña están el presupuesto, las previsiones de gastos y la salud financiera del mes.",
"Lançamento automático e extratos":"Registro automático y extractos",
"No Android, as compras e os Pix avisados pelo banco viram sugestões de gasto no Resumo: um toque lança. Em Gastos › Importar extrato, escolha um ou vários arquivos OFX ou CSV do banco e confira antes de importar.":"En Android, las compras y los Pix avisados por el banco se vuelven sugerencias de gasto en el Resumen: un toque los registra. En Gastos › Importar extracto, elige uno o varios archivos OFX o CSV del banco y revísalos antes de importar.",
"Parcelas e financiamentos":"Cuotas y financiamientos",
"Em Gastos › Parceladas, cadastre compras parceladas, financiamentos e empréstimos. Toque num item para ver o saldo devedor e todas as parcelas, pagar, abater ou exportar em PDF.":"En Gastos › A cuotas, registra compras en cuotas, financiamientos y préstamos. Toca un elemento para ver el saldo pendiente y todas las cuotas, pagar, amortizar o exportar en PDF.",
"Cadastre aplicações, ações e metas. O app projeta quanto vão render com CDI, Selic e IPCA e mostra quanto falta para cada meta.":"Registra inversiones, acciones y metas. La app proyecta cuánto van a rendir con CDI, Selic e IPCA y muestra cuánto falta para cada meta.",
"Pergunte \"quanto gastei com mercado este mês?\" ou escreva (ou fale) \"gastei 30 no almoço\" para lançar sem abrir formulário.":"Pregunta \"¿cuánto gasté en el mercado este mes?\" o escribe (o di) \"gasté 30 en el almuerzo\" para registrar sin abrir un formulario.",
"Com um tema especial, quem responde é o personagem do tema, com as falas dele.":"Con un tema especial, quien responde es el personaje del tema, con sus frases.",
"Começam desligados neste aparelho. Ligue em Configurações › Lembretes (o Android pede a permissão de notificações) e escolha os tipos: contas a vencer, antes e no dia, parcelas de financiamentos e os avisos das previsões de gastos. Desligue a economia de bateria do app para os avisos chegarem na hora.":"Empiezan desactivados en este dispositivo. Actívalos en Ajustes › Recordatorios (Android pide el permiso de notificaciones) y elige los tipos: cuentas por vencer, antes y el mismo día, cuotas de financiamientos y los avisos de las previsiones de gastos. Desactiva el ahorro de batería de la app para que los avisos lleguen a tiempo.",
"Tudo sincroniza com a sua conta Google, com uma cópia por dia. Em Configurações › Conta compartilhada, dá para dividir os dados com outra pessoa.":"Todo se sincroniza con tu cuenta de Google, con una copia por día. En Ajustes › Cuenta compartida, puedes compartir los datos con otra persona.",
"Mais de 180 temas especiais, cada um com personagem, cenário animado e estilo de interface próprios, além de cores, moeda e país,":"Más de 180 temas especiales, cada uno con personaje, escenario animado y estilo de interfaz propios, además de colores, moneda y país,",
"abas do menu, bloqueio com senha, widgets na tela inicial (com ou sem os valores) e o modo divertido, com mais de 100 conquistas. Tudo em Configurações.":"pestañas del menú, bloqueo con contraseña, widgets en la pantalla de inicio (con o sin los valores) y el modo divertido, con más de 100 logros. Todo en Ajustes.",
