"É o formato \"OFX\" ou \"Money\" que quase todo banco oferece ao exportar o extrato. Não precisa ajustar nada.":"Es el formato \"OFX\" o \"Money\" que casi todos los bancos ofrecen al exportar el extracto. No hace falta ajustar nada.",
"2. CSV (planilha em texto)":"2. CSV (hoja de cálculo en texto)",
"A primeira linha precisa ter os nomes das colunas, separadas por ponto e vírgula ou vírgula:":"La primera línea debe tener los nombres de las columnas, separados por punto y coma o coma:",
