"Valores negativos entram como gastos e positivos como ganhos (numa fatura de cartão é o contrário; você escolhe na próxima tela). Antes de gravar, o app mostra a lista para você conferir e desmarca o que já existe.":"Los valores negativos entran como gastos y los positivos como ingresos (en una factura de tarjeta es al revés; lo eliges en la siguiente pantalla). Antes de guardar, la app muestra la lista para que la revises y desmarca lo que ya existe.",
"Dá para escolher vários extratos de uma vez (meses ou bancos diferentes): cada lançamento entra no dia e no mês da data dele, e o que aparece em dois arquivos entra uma vez só.":"Puedes elegir varios extractos a la vez (meses o bancos distintos): cada movimiento entra en el día y el mes de su fecha, y lo que aparece en dos archivos entra una sola vez.",
