"O saldo soma os ganhos e desconta os gastos em que o campo de banco/conta tiver exatamente este nome. Lançamentos com dia depois de hoje ainda não contam, e compras no crédito só saem quando a fatura é paga (configure em Gastos → Faturas do cartão).":"El saldo suma los ingresos y resta los gastos cuyo campo de banco/cuenta tenga exactamente este nombre. Los movimientos con fecha posterior a hoy aún no cuentan, y las compras con tarjeta de crédito solo salen cuando se paga la factura (se configura en Gastos → Facturas de la tarjeta).",
