"Fechamento: compras avulsas com dia depois dele entram na fatura do mês seguinte. Pagamento: a fatura de um mês sai da conta no mês seguinte, nesse dia (sem dia, no começo do mês).":"Cierre: las compras puntuales con día posterior a él entran en la factura del mes siguiente. Pago: la factura de un mes sale de la cuenta el mes siguiente, ese día (sin día, a principios de mes).",
