"Sem dia, vale até o último dia do mês. Os gastos da categoria (ou todos os gastos, ou tudo no cartão de crédito, nas opções gerais) até esse dia enchem a barra; o que faltar do previsto já entra no saldo previsto do mês.":"Sin día, vale hasta el último día del mes. Los gastos de la categoría (o todos los gastos, o todo en la tarjeta de crédito, en las opciones generales) hasta ese día llenan la barra; lo que falte del valor previsto ya entra en el saldo previsto del mes.",
"{}: cotação atual {}. Deixe em branco para desligar.":"{}: cotización actual {}. Déjalo en blanco para desactivar.",
"O valor de baixo precisa ser menor que o de cima.":"El valor de abajo debe ser menor que el de arriba.",
"Com o app aberto, o preço é conferido a cada atualização das cotações. Com ele fechado, o celular confere mais ou menos de hora em hora e avisa por notificação (precisa das notificações ligadas e de internet). Não é um aviso em tempo real.":"Con la app abierta, el precio se revisa en cada actualización de cotizaciones. Con ella cerrada, el celular revisa más o menos cada hora y avisa con una notificación (necesita notificaciones activadas e internet). No es un aviso en tiempo real.",
