"· desfeita (na Lixeira)":"· deshecha (en la Papelera)",
"Esvaziar a lixeira? Os lançamentos excluídos não poderão mais ser restaurados.":"¿Vaciar la papelera? Los movimientos eliminados ya no se podrán restaurar.",
"Desfeito:":"Deshecho:",
"Exame":"Exame",
"mercado financeiro ibovespa":"mercado financeiro ibovespa",
