"Duas contas Google vendo e lançando nos mesmos dados, cada pessoa no próprio celular. Cada lançamento mostra quem fez; nome e aparência continuam de cada um.":"Dos cuentas de Google viendo y registrando en los mismos datos, cada persona en su propio celular. Cada movimiento muestra quién lo hizo; nombre y apariencia siguen siendo de cada uno.",
"Prévia no PC: a conta compartilhada só funciona no app instalado no celular.":"Vista previa en PC: la cuenta compartida solo funciona en la app instalada en el celular.",
