"Avisa quando outra pessoa entra na conta ou adiciona/edita um gasto, ganho ou investimento: na tela do app e, com ele fechado, por notificação do celular. O celular confere a cada 15 minutos, mais ou menos (o app não tem servidor para avisar na hora).":"Avisa cuando otra persona entra a la cuenta o añade/edita un gasto, ingreso o inversión: en la pantalla de la app y, con ella cerrada, por notificación del celular. El celular revisa cada 15 minutos, más o menos (la app no tiene servidor para avisar al instante).",
"{}Atividade recente{}":"{}Actividad reciente{}",
"Os lançamentos ficam numa planilha do Google compartilhada entre vocês (não edite a planilha à mão). Cópias diárias e comprovantes continuam de cada um.":"Los movimientos quedan en una hoja de cálculo de Google compartida entre ustedes (no edites la hoja a mano). Las copias diarias y los comprobantes siguen siendo de cada uno.",
