"O app cria uma planilha vazia na sua conta Google e a compartilha com a outra pessoa. Os seus lançamentos de hoje não entram: continuam guardados na sua conta. Depois, ela abre o app e cola o código do convite.":"La app crea una hoja de cálculo vacía en tu cuenta de Google y la comparte con la otra persona. Tus movimientos de hoy no entran: siguen guardados en tu cuenta. Después, ella abre la app y pega el código de invitación.",
"O app cria uma planilha na sua conta Google com os seus lançamentos e a compartilha com a outra pessoa, que recebe um e-mail do Google. Depois, ela abre o app, entra com a conta convidada e cola o código do convite.":"La app crea una hoja de cálculo en tu cuenta de Google con tus movimientos y la comparte con la otra persona, que recibe un correo de Google. Después, ella abre la app, entra con la cuenta invitada y pega el código de invitación.",
