"1. Se aparecer \"O Google não verificou este app\", toque em \"Avançado\" e depois em \"Acessar Cofrim (não seguro)\". O aviso aparece porque o app ainda não passou pela verificação do Google; os dados ficam só na sua conta. 2. Marque as caixas de permissão (Planilhas e arquivos do Drive criados pelo app). 3. Toque em \"Continuar\".":"1. Si aparece \"Google no ha verificado esta app\", toca \"Avanzado\" y luego \"Ir a Cofrim (no seguro)\". El aviso aparece porque la app aún no pasó por la verificación de Google; tus datos quedan solo en tu cuenta. 2. Marca las casillas de permiso (Hojas de cálculo y archivos de Drive creados por la app). 3. Toca \"Continuar\".",
"Agora o Google vai pedir sua permissão para o app criar e ler a planilha da conta compartilhada. {}":"Ahora Google te pedirá permiso para que la app cree y lea la hoja de cálculo de la cuenta compartida. {}",
