"Deslize a tela para os lados para trocar de mês. Num lançamento, deslize para a esquerda para excluir e, numa conta com vencimento, para a direita para marcar como paga.":"Desliza la pantalla hacia los lados para cambiar de mes. En un movimiento, desliza a la izquierda para eliminar y, en una cuenta con vencimiento, a la derecha para marcarla como pagada.",
