"Nenhuma categoria neste grupo ainda.":"Todavía no hay categorías en este grupo.",
"A categoria escolhida foi apagada. Escolha outra.":"La categoría elegida fue eliminada. Elige otra.",
"Orçamento das categorias e dos grupos":"Presupuesto de las categorías y de los grupos",
