"Orçamento mensal por grupo e categoria":"Presupuesto mensual por grupo y categoría",
"Grupo {} (todas as categorias) — limite por mês":"Grupo {} (todas las categorías) — límite por mes",
"Com \"Sim\", se você gastar menos que o limite de uma categoria ou de um grupo, a diferença soma ao limite dele no mês seguinte.":"Con \"Sí\", si gastas menos que el límite de una categoría o de un grupo, la diferencia se suma a su límite el mes siguiente.",
"O limite de um grupo soma os gastos de todas as categorias dele e avisa como o das categorias (Configurações › Avisos de valores).":"El límite de un grupo suma los gastos de todas sus categorías y avisa como el de las categorías (Ajustes › Avisos de valores).",
"Orçamento do grupo {} estourou: {}.":"Presupuesto del grupo {} superado: {}.",
