"Apagar o grupo \"{}\" e as {} categoria(s) dele?":"¿Borrar el grupo \"{}\" y sus {} categoría(s)?",
"Nenhum lançamento é apagado: {} lançamento(s) passam para \"Outros\" (ou para a categoria do app com o mesmo nome).":"No se borra ningún movimiento: {} movimiento(s) pasan a \"Otros\" (o a la categoría de la app con el mismo nombre).",
"As categorias que já vêm no app não se apagam: ficam escondidas em \"Outros\".":"Las categorías que vienen con la app no se borran: quedan ocultas en \"Otros\".",
"Restaurar os grupos padrão de gastos?":"¿Restaurar los grupos predeterminados de gastos?",
"Restaurar os grupos padrão de ganhos?":"¿Restaurar los grupos predeterminados de ingresos?",
"Os grupos que vêm no app voltam com o nome, o ícone e a cor deles, e as categorias do app voltam para eles.":"Los grupos que vienen con la app vuelven con su nombre, ícono y color, y las categorías de la app vuelven a ellos.",
"Os grupos e as categorias que você criou ficam como estão; nenhum lançamento muda.":"Los grupos y las categorías que creaste quedan como están; ningún movimiento cambia.",
"Grupos padrão restaurados.":"Grupos predeterminados restaurados.",
"Escolher a categoria por grupo":"Elegir la categoría por grupo",
"Novo ganho ou gasto › Categoria":"Nuevo ingreso o gasto › Categoría",
"No topo ficam as categorias usadas por último (um toque escolhe); embaixo, os grupos. Toque num grupo para ver as categorias dele e escolher uma, ou crie uma nova ali mesmo. A busca acha a categoria pelo nome, sem acentos (ex.: \"cafe\" acha Café e lanches); sem resultado, cria com o nome digitado. \"Novo grupo\" cria um grupo sem sair do lançamento, e segurar um grupo (ou uma categoria) abre o Editar e o Excluir. A escolhida aparece como \"Grupo › Categoria\"; toque nela para trocar.":"Arriba están las categorías que usaste por última vez (un toque elige); abajo, los grupos. Toca un grupo para ver sus categorías y elegir una, o crea una nueva ahí mismo. La búsqueda encuentra la categoría por el nombre, sin acentos (ej.: \"cafe\" encuentra \"Café\"); sin resultados, la crea con el nombre escrito. \"Grupo nuevo\" crea un grupo sin salir del registro, y mantener presionado un grupo (o una categoría) abre Editar y Eliminar. La elegida aparece como \"Grupo › Categoría\"; tócala para cambiarla.",
"Grupos de categorias":"Grupos de categorías",
"As categorias ficam em grupos (ex.: Lazer reúne Bares, Cinema e Viagens), separados para gastos e ganhos. Toque em um grupo para ver as categorias dele; \"Nova categoria\" cria já dentro do grupo e \"Editar grupo\" muda o nome, o ícone e a cor. Para mudar uma categoria de grupo, use o Editar dela. Ao excluir um grupo, escolha entre mover as categorias para Outros (nada se perde) ou apagá-las também: os lançamentos nunca são apagados. \"Outros\" não se exclui, e \"Restaurar grupos padrão\" traz de volta os grupos do app.":"Las categorías están en grupos (ej.: Ocio reúne Bares, Cine y Viajes), separados para gastos e ingresos. Toca un grupo para ver sus categorías; \"Nueva categoría\" crea una dentro del grupo y \"Editar grupo\" cambia el nombre, el ícono y el color. Para cambiar una categoría de grupo, usa su Editar. Al eliminar un grupo, elige entre mover sus categorías a Otros (no se pierde nada) o borrarlas también: los movimientos nunca se borran. \"Otros\" no se elimina, y \"Restaurar grupos predeterminados\" trae de vuelta los grupos de la app.",
