"Toque no + (ou nos atalhos do Resumo) e informe só o valor e a categoria; o resto fica em \"Mais opções\". Os gastos que você mais repete viram botões. Num salário, escolha em Mais opções o dia em que cai, como o {}º dia útil.":"Toca el + (o los accesos del Resumen) e indica solo el valor y la categoría; el resto está en \"Más opciones\". Los gastos que más repites se vuelven botones. En un salario, elige en Más opciones el día en que cae, como el {}.º día hábil.",
