"Português, inglês ou espanhol: o app inteiro muda de idioma (telas, avisos, guia, novidades, frases dos temas e notificações), e o assistente entende e responde no idioma escolhido. O que você digitou fica como está.":"Portugués, inglés o español: toda la app cambia de idioma (pantallas, avisos, guía, novedades, frases de los temas y notificaciones), y el asistente entiende y responde en el idioma elegido. Lo que escribiste queda como está.",
"App inteiro em inglês e espanhol":"Toda la app en inglés y español",
"Com o idioma em inglês ou espanhol, tudo muda: telas, avisos, guia, novidades, conquistas, frases do mascote nos temas e notificações. O assistente entende e responde no idioma escolhido. O que você digitou (descrições, nomes, bancos) fica como está.":"Con el idioma en inglés o español, todo cambia: pantallas, avisos, guía, novedades, logros, frases de la mascota en los temas y notificaciones. El asistente entiende y responde en el idioma elegido. Lo que escribiste (descripciones, nombres, bancos) queda como está.",
