"Para o que não é todo mês nem uma vez por ano: \"A cada X meses\" (PLR a cada 6 meses, em junho e dezembro) conta a partir do primeiro mês; \"Meses escolhidos\" (IPVA em jan, fev e mar) marca os meses numa grade de 12. Os dois aceitam o dia do mês e as regras de dia útil, o vencimento e o \"Até\", e aparecem no grupo \"Em alguns meses\", com uma etiqueta que diz quando repetem. Um anual vira um deles pela edição.":"Para lo que no es todos los meses ni una vez al año: \"Cada X meses\" (participación en utilidades cada 6 meses, en junio y diciembre) cuenta desde el primer mes; \"Meses elegidos\" (impuesto del auto en ene, feb y mar) marca los meses en una cuadrícula de 12. Los dos aceptan el día del mes y las reglas de día hábil, el vencimiento y el \"Hasta\", y aparecen en el grupo \"En algunos meses\", con una etiqueta que dice cuándo se repiten. Un anual se convierte en uno de ellos al editarlo.",
"No Tipo de um ganho ou gasto, \"A cada X meses\" (ex.: PLR a cada 6 meses, em junho e dezembro) e \"Meses escolhidos\" (ex.: IPVA em jan, fev e mar, numa grade de 12 meses). Contam só nos meses certos, com dia útil e vencimento, e aparecem no grupo \"Em alguns meses\". Importar planilha também sugere esses tipos.":"En el Tipo de un ingreso o gasto, \"Cada X meses\" (ej.: participación en utilidades cada 6 meses, en junio y diciembre) y \"Meses elegidos\" (ej.: impuesto del auto en ene, feb y mar, en una cuadrícula de 12 meses). Cuentan solo en los meses correctos, con día hábil y vencimiento, y aparecen en el grupo \"En algunos meses\". Importar hoja de cálculo también sugiere estos tipos.",
