"Nuvens calmas no teto da capela.":"Nubes tranquilas en el techo de la capilla.",
"Os dedos não se tocaram: faltam {v}.":"Los dedos no se tocaron: faltan {v}.",
"Afresco completo: {v} guardados.":"Fresco terminado: {v} ahorrados.",
"Asas batendo de alegria, {nome}!":"¡Alas aleteando de alegría, {nome}!",
"Andaime firme, pincel na mão.":"Andamio firme, pincel en mano.",
"Um anjinho de olho nas contas.":"Un angelito vigilando las cuentas.",
"Tinta escorreu do teto: faltam {v}.":"La pintura goteó del techo: faltan {v}.",
"Estica o braço mais um pouco, {nome}.":"Estira el brazo un poco más, {nome}.",
"Céu pintado, sobraram {v}.":"Cielo pintado, sobran {v}.",
"Criou um mês lindo, {nome}!":"¡Creaste un mes precioso, {nome}!",
"Túnica rosa e nuvens leves.":"Túnica rosa y nubes ligeras.",
"Esboço pronto, cores depois.":"Boceto listo, colores después.",
"Rachadura no afresco: faltam {v}.":"Grieta en el fresco: faltan {v}.",
"Até o teto tem conserto, {nome}.":"Hasta el techo tiene arreglo, {nome}.",
